TERRACE = 8.13


def outer_court():
    out = []
    # Gate of Supreme Harmony: 3.44 m marble platform (the OSM platform and stairs, scaled), double-eaved hip-and-gable, 23.8 m
    out += hall(-2.45, 304.15, 0, 54.9, 26.5, 3.44, 11.0, 22.7, "xieshan", Lb=48.2, Db=20.6, plat=False,
                double=(13.4, 42.0, 14.6, 15.2, 48.1, 20.6), chiwen=True)
