# ── Ground, moat, river, bridges, trees ──────────────────────────────────────
def tree(x, z, h, r, c):
    hc = h * 0.78
    y0 = h - hc
    crown = lathe([(r * 0.55, y0), (r, y0 + hc * 0.35), (r * 0.85, y0 + hc * 0.7), (0.0, h)], c, 5)
    crown.f = crown.f
    trunk = cyl(0.25, 0.2, y0 + 0.3, (0.30, 0.24, 0.18), 4, caps=False)
    return [crown.T(x, 0, z), trunk.T(x, 0, z)]


def site(D, stones, blocked):
    out, wat = [], []
    # the moat: water and stone banks
    moat = D["moat"]
    # (the ground inside the footprint is levelled to y = 0 in Offlined, so the water is drawn just above it,
    # between stone kerbs, rather than in the real 6 m deep channel)
    wat.append(cap(moat, 0.18, WATER))
    for a, b, n in ring_edges(moat):
        Lw = math.hypot(b[0] - a[0], b[1] - a[1])
        ang = math.atan2(b[1] - a[1], b[0] - a[0])
        k = B(-Lw / 2 - 0.4, Lw / 2 + 0.4, FOUND, 0.65, -0.4, 0.4, STONE)
        out.append(place(k, ang, (a[0] + b[0]) / 2 + n[0] * 0.4, (a[1] + b[1]) / 2 + n[1] * 0.4))
    # paving inside the moat (inner edge of the moat, closed across the forecourt of the Meridian Gate)
    Wp = np.array(WALL_Q)
    def dwall(p):
        best = 1e9
        for i in range(4):
            a, b = Wp[i], Wp[(i + 1) % 4]
            t = np.clip(np.dot(p - a, b - a) / np.dot(b - a, b - a), 0, 1)
            best = min(best, np.linalg.norm(p - (a + t * (b - a))))
        return best
    M = np.array(moat)
    near = [dwall(p) < 45 for p in M]
    k0 = next(i for i in range(len(M)) if near[i] and not near[i - 1])
    chain = []
    i = k0
    while near[i % len(M)]:
        chain.append(tuple(M[i % len(M)])); i += 1
    if chain[0][1] > chain[-1][1]:
        pass
    paving = chain + [(-97.8, 553.5), (91.1, 552.1)] if chain[-1][0] < 0 else chain + [(91.1, 552.1), (-97.8, 553.5)]
    water = [w for w in D["water"]]
    out.append(cap(paving, 0.10, PAVE, holes=water))
    out.append(cap(rect(-4.6, 1.4, -455.0, 454.0), 0.14, PAVE_L))                  # the Imperial Way on the axis
    # Inner Golden Water River and ponds: water, banks, balustrades
    bridges = [b for _, b in D["bridge"]]
    for w in water:
        wat.append(cap(w, 0.16, WATER))
        out.append(walls(w, FOUND, 0.30, STONE, hole=True))
        for a, b, n in ring_edges(w):
            mx, mz = (a[0] + b[0]) / 2 - n[0] * 0.4, (a[1] + b[1]) / 2 - n[1] * 0.4
            if any(pip(mx + n[0] * 0.8, mz + n[1] * 0.8, br) or pip(mx - n[0] * 1.2, mz - n[1] * 1.2, br) for br in bridges):
                continue
            out += balustrade((a[0] - n[0] * -0.3, a[1] - n[1] * -0.3), (b[0] - n[0] * -0.3, b[1] - n[1] * -0.3), 0.10, MARBLE, step=4.5)
    for br in bridges:
        out.append(extrude(br, FOUND, 0.75, MARBLE))
        for a, b, n in ring_edges(br):
            mx, mz = (a[0] + b[0]) / 2 + n[0] * 0.8, (a[1] + b[1]) / 2 + n[1] * 0.8
            if any(pip(mx, mz, w) for w in water):
                out += balustrade((a[0] - n[0] * 0.25, a[1] - n[1] * 0.25), (b[0] - n[0] * 0.25, b[1] - n[1] * 0.25), 0.75, MARBLE, step=3.0)
    # woods, lawns, gardens and their trees
    pts = [tuple(p) for p in D["trees"]]
    for kind, P in D["wood"]:
        out.append(cap(P, 0.20, GRASS))
        if kind in ("wood", "forest"):
            x0, x1, z0, z1 = bbox(P)
            area = abs(ring_area(P))
            n = int(min(28, area / 170))
            for _ in range(n * 3):
                if n <= 0:
                    break
                x, z = rng.uniform(x0, x1), rng.uniform(z0, z1)
                if pip(x, z, P):
                    pts.append((x, z)); n -= 1
    for P in D["garden"]:
        out.append(cap(P, 0.20, GRASS))
    for L in D["rows"]:
        for (x0, z0), (x1, z1) in zip(L[:-1], L[1:]):
            d = math.hypot(x1 - x0, z1 - z0)
            for k in range(int(d / 7) + 1):
                t = k * 7 / max(d, 1e-6)
                pts.append((x0 + (x1 - x0) * t, z0 + (z1 - z0) * t))
    # the Imperial Garden: old cypresses between the pavilions and halls
    for x in np.arange(-66, 64, 10.0):
        for z in np.arange(-428, -362, 10.0):
            pts.append((x + rng.uniform(-2.5, 2.5), z + rng.uniform(-2.5, 2.5)))
    trees = []
    for x, z in pts:
        if blocked(x, z) or any(pip(x, z, w) for w in water):
            continue
        h = rng.uniform(8, 14)
        trees += tree(x, z, h, h * rng.uniform(0.26, 0.36), sc(LEAF if rng.random() < 0.6 else LEAF_L, 0.06))
    return out, wat, trees, len(trees) // 2


def convex_hull(P):
    P = sorted(set(map(tuple, P)))
    def half(seq):
        h = []
        for p in seq:
            while len(h) >= 2 and (h[-1][0] - h[-2][0]) * (p[1] - h[-2][1]) - (h[-1][1] - h[-2][1]) * (p[0] - h[-2][0]) <= 0:
                h.pop()
            h.append(p)
        return h
    lower, upper = half(P), half(P[::-1])
    return lower[:-1] + upper[:-1]


def main():
    D = json.loads(_DATA)
    out_dir = ROOT / "models" / "Q80290"
    out_dir.mkdir(parents=True, exist_ok=True)
    items = list(D["stone"])
    near_corner = lambda s: any(abs(np.mean([p[0] for p in s[1]]) - x) < 32 and abs(np.mean([p[1] for p in s[1]]) - z) < 32
                                for x, z in WALL_Q)
    items = [s for s in items if not near_corner(s)]           # the corner towers' own parts: built by corner_tower()
    stones = Stones(items)
    for s in list(stones.items):                           # the West Glorious Gate's ramps: the east ones mirrored
        if 638768057 <= s["id"] <= 638768063:
            m = dict(s); m["P"] = [(-x, z) for x, z in s["P"]][::-1]
            if s["dir"]:
                vx, vz = bearing_vec(s["dir"]); m["dir"] = None; m["dirv"] = (-vx, vz)
            m["bb"] = bbox(m["P"])
            stones.items.append(m)
    # footprints of the buildings (no trees there)
    fps = [bbox(r) + (r,) for _, _, r, *_ in D["b"]]
    def blocked(x, z):
        for x0, x1, z0, z1, r in fps:
            if x0 - 3 <= x <= x1 + 3 and z0 - 3 <= z <= z1 + 3:
                return True
        return stones.level(x, z, flat_only=False) > 0
    bld = build_buildings(D, stones)
    cus = city_wall() + corner_towers() + meridian_gate() + shenwumen() + side_gate(1) + side_gate(-1) + outer_court()
    st = stones.meshes()
    ground, wat, trees, ntrees = site(D, stones, blocked)
    parts = [("palace_buildings", merge(bld)), ("walls_gates_halls", merge(cus)), ("terraces", merge(st)),
             ("ground", merge(ground)), ("trees", merge(trees)), ("water", merge(wat), {"material": "water"})]
    for _, m, *_ in parts:
        compact(_drop_degenerate(m))
    tris, size = write_glb(out_dir / "model.glb", parts, roughness=0.85, materials={"water": {"metallic": 0.3, "roughness": 0.15}})
    allv = np.vstack([p[1].v for p in parts])
    lo, hi = allv.min(0), allv.max(0)
    print(f"model.glb: {tris:,} triangles, {size / 2**20:.2f} MB, extent x {lo[0]:.1f}..{hi[0]:.1f}, "
          f"y {lo[1]:.1f}..{hi[1]:.1f}, z {lo[2]:.1f}..{hi[2]:.1f}; trees {ntrees}")
    for name, m, *_ in parts:
        print(f"  {name}: {m.tris:,}")
    hull = convex_hull(np.array(D["moat"] + [(-64.2, 563.4), (62.0, 563.4)]))
    fp = [[round(x, 1), round(z, 1)] for x, z in offset(hull, 1.0)]
    meta = out_dir / "meta.json"
    if meta.exists():
        mj = json.loads(meta.read_text(encoding="utf-8"))
        mj["triangles"] = int(tris)
        mj["footprint"] = fp
        meta.write_bytes((json.dumps(mj, ensure_ascii=False, indent=2) + "\n").encode("utf-8"))


